WITH
case_set AS (SELECT DISTINCT c.concept_id FROM `wb-silky-artichoke-2408.C2024Q3R8.cb_criteria` c JOIN (SELECT CAST(cr.id AS STRING) id FROM `wb-silky-artichoke-2408.C2024Q3R8.cb_criteria` cr WHERE concept_id IN (140168,36715780,37205056,37205057,4031141,4031142,4031649,4063433,4223485) AND full_text LIKE '%_rank1]%') a ON (c.path LIKE CONCAT('%.',a.id,'.%') OR c.path LIKE CONCAT('%.',a.id) OR c.path LIKE CONCAT(a.id,'.%') OR c.path=a.id) WHERE c.is_standard=1 AND c.is_selectable=1),
arthritis_set AS (SELECT DISTINCT c.concept_id FROM `wb-silky-artichoke-2408.C2024Q3R8.cb_criteria` c JOIN (SELECT CAST(cr.id AS STRING) id FROM `wb-silky-artichoke-2408.C2024Q3R8.cb_criteria` cr WHERE concept_id IN (81931,40319772,4083682,46274123) AND full_text LIKE '%_rank1]%') a ON (c.path LIKE CONCAT('%.',a.id,'.%') OR c.path LIKE CONCAT('%.',a.id) OR c.path LIKE CONCAT(a.id,'.%') OR c.path=a.id) WHERE c.is_standard=1 AND c.is_selectable=1),
exclude_set AS (SELECT DISTINCT c.concept_id FROM `wb-silky-artichoke-2408.C2024Q3R8.cb_criteria` c JOIN (SELECT CAST(cr.id AS STRING) id FROM `wb-silky-artichoke-2408.C2024Q3R8.cb_criteria` cr WHERE concept_id IN (140168,36715780,37205056,37205057,4031141,4031142,4031649,4063433,4223485,81931,40319772,4083682,46274123) AND full_text LIKE '%_rank1]%') a ON (c.path LIKE CONCAT('%.',a.id,'.%') OR c.path LIKE CONCAT('%.',a.id) OR c.path LIKE CONCAT(a.id,'.%') OR c.path=a.id) WHERE c.is_standard=1 AND c.is_selectable=1),
drug_roots AS (SELECT DISTINCT c.concept_id FROM `wb-silky-artichoke-2408.C2024Q3R8.cb_criteria` c JOIN (SELECT CAST(cr.id AS STRING) id FROM `wb-silky-artichoke-2408.C2024Q3R8.cb_criteria` cr WHERE concept_id IN (1305058,35603563,937368,1593700,45892883,929638,1151789,35200139,40161532,44816294,1592513,1511348,19010482,1119119,912263) AND full_text LIKE '%_rank1]%') a ON (c.path LIKE CONCAT('%.',a.id,'.%') OR c.path LIKE CONCAT('%.',a.id) OR c.path LIKE CONCAT(a.id,'.%') OR c.path=a.id) WHERE c.is_standard=1 AND c.is_selectable=1),
drug_set AS (SELECT DISTINCT ca.descendant_id concept_id FROM `wb-silky-artichoke-2408.C2024Q3R8.cb_criteria_ancestor` ca JOIN drug_roots d ON ca.ancestor_id=d.concept_id),
dx AS (SELECT c.person_id,MIN(DATE(c.condition_start_datetime)) first_dx FROM `wb-silky-artichoke-2408.C2024Q3R8.condition_occurrence` c JOIN case_set s ON c.condition_concept_id=s.concept_id GROUP BY person_id),tx AS (SELECT d.person_id,MIN(d.drug_exposure_start_date) first_tx FROM `wb-silky-artichoke-2408.C2024Q3R8.drug_exposure` d JOIN drug_set s ON d.drug_concept_id=s.concept_id GROUP BY person_id) SELECT person_id,first_dx,first_tx FROM dx FULL OUTER JOIN tx USING(person_id)